SELECT id, code, COALESCE(display_title,'') AS display_title, title, level, seq, status, CASE WHEN COALESCE(item_codes,'') = '' THEN 0 ELSE LENGTH(item_codes) - LENGTH(REPLACE(item_codes, ',', '')) + 1 END AS item_count, CASE WHEN COALESCE(point_codes,'') = '' THEN 0 ELSE LENGTH(point_codes) - LENGTH(REPLACE(point_codes, ',', '')) + 1 END AS point_count FROM textbook_import_draft WHERE task_id = CAST(:task_id AS INTEGER) ORDER BY seq ASC, id ASC
